package in.recallradar;
import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import org.springframework.transaction.annotation.Transactional; import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional class InvitationServiceTest {@Autowired InvitationService invitations; @Autowired TenantService tenants; @Autowired UserRepository users; @Autowired MembershipRepository memberships;
@Test void administratorCanCreateAndNewUserCanAcceptRoleScopedInvite(){var admin=users.save(new AppUser("Admin","admin-invite@test.example","hash"));var org=tenants.createWorkspace(admin,"Invite Kitchens");var member=memberships.findByUserIdAndOrganizationId(admin.id,org.id).orElseThrow();var invite=invitations.create(member,new InvitationRequest("team-invite@test.example",OrganizationRole.WAREHOUSE_MANAGER));assertTrue(invite.invitePath().contains("invite="));var token=invitations.accept(new AcceptInvitationRequest(invite.inviteToken(),"Warehouse User","team-invite@test.example","SafePassword@2026"));assertNotNull(token.accessToken());var person=users.findByEmailIgnoreCase("team-invite@test.example").orElseThrow();assertEquals(OrganizationRole.WAREHOUSE_MANAGER,memberships.findByUserIdAndOrganizationId(person.id,org.id).orElseThrow().role);}}
